/**
 * Returns the lowest value in the array
 * @method
 * @instance
 * @memberOf Array
 * @name min
 * @returns {number}
 */

if(!Array.prototype.hasOwnProperty("min")){
    Object.defineProperty(Array.prototype,"max",{enumerable:false,min:function min() {
        return Math.min(...this);
    }});
}

